Object.assign(window.TEM8_DICTIONARY, {"onwards":{"media":{"uk":"media/uk/onwards__gb_1.mp3","us":"media/us/onwards__us_1.mp3"},"oxford":{"phon":"ˈɒnwədz","pos":"adverb","senses":[{"en":"continuing from a particular time","cn":"从（某时）起一直","ex":{"en":"They lived there from the 1980s onwards.","cn":"他们从 20 世纪 80 年代起一直住在那里。"}},{"en":"forward","cn":"向前；前往","lab":"formal","ex":{"en":"We drove onwards towards the coast.","cn":"我们驱车前往海滨。"}}]},"examples":[{"en":"They lived there from the 1980s onwards.","cn":"他们从 1980 年代起一直住在那里。"},{"en":"The pool is open from 7 a.m. onwards.","cn":"游泳池从早上 7 点起开放。"}]},"one-sided":{"oxford":{"phon":"ˌwʌn ˈsaɪdɪd","pos":"adjective","senses":[{"en":"showing only one side of the situation; not balanced","cn":"片面的；偏颇的","lab":"disapproving","ex":{"en":"The press were accused of presenting a very one-sided picture of the issue.","cn":"新闻界被指责对这件事的报道非常片面。"}},{"en":"involving people who have different abilities; involving one person more than another","cn":"实力悬殊的；一边倒的","ex":{"en":"a totally one-sided match","cn":"实力非常悬殊的比赛"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"不均衡的；一边倒的；悬殊的","en":"If you say that an activity or relationship is one-sided, you think that one of the people or groups involved does much more than the other or is much stronger than the other.","ex":{"en":"The negotiating was completely one-sided","cn":"谈判完全呈一边倒之势。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"片面的；偏颇的；不公正的","en":"If you describe someone as one-sided, you are critical of what they say or do because you think it shows that they have considered only one side of an issue or event.","ex":{"en":"The organisation still believes the government is being one sided","cn":"该组织仍然认为政府有失公允。"}}]},"media":{"uk":"media/uk/one_sided_1_gb_1.mp3","us":"media/us/one_sided_1_us_1.mp3"},"examples":[{"en":"The press were accused of presenting a very one-sided picture of the issue.","cn":"新闻界被指责对这件事的报道非常片面。"},{"en":"a one-sided conversation (= in which one person talks most of the time)","cn":"一边倒的交谈"}]},"one-man":{"oxford":{"phon":"ˌwʌn ˈmæn","pos":"adjective","senses":[{"en":"done or controlled by one person only; suitable for one person","cn":"适于一个人的；由一个人操作的","ex":{"en":"a one-man show/business","cn":"独角戏；一个人经营的生意"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"单人表演的","en":"A one-man performance is given by only one man rather than by several people.","ex":{"en":"I saw him do his one-man show in London, which I loved.","cn":"我在伦敦看过他的独角戏，非常喜欢。"}},{"pos":"ADJ 形容词","cn":"一个人经营（或控制）的","en":"A one-man organization, such as a business or type of government, is controlled by one person, rather than by several people.","ex":{"en":"It has grown from a one-man business to a multi-million dollar business with close to $10 million in assets","cn":"它已从一个人经营的生意发展成资产规模近千万、业务额达数百万美元的公司。"}}]},"media":{"uk":"media/uk/one_man_1_gb_1.mp3","us":"media/us/one_man_1_us_1.mp3"},"examples":[{"en":"a one-man show/business","cn":"独角戏；一个人经营的生意"},{"en":"a one-man tent","cn":"单人帐篷"}]},"oneself":{"media":{"uk":"media/uk/oneself__gb_1.mp3","us":"media/us/oneself__us_1.mp3"},"oxford":{"phon":"wʌnˈself","pos":"pronoun","senses":[{"en":"used as the object of a verb or preposition when ‘one’ is the subject of the verb or is understood as the subject","cn":"（one 作动词的主语时，oneself 作动词或介词的宾语）自己，自身","ex":{"en":"One has to ask oneself what the purpose of the exercise is.","cn":"大家必须问一问自己，这个锻炼的目的是什么。"}},{"en":"used to emphasize one","cn":"（用以强调 one）亲自，自己","ex":{"en":"One likes to do it oneself.","cn":"人都喜欢亲自去做。"}}]},"collins":{"senses":[{"pos":"PRON-REFL 反身代词","cn":"（用作从句中动词或代词的宾语，指代动词主语“我”或“任何人”）自己，自身","en":"A speaker or writer uses oneself as the object of a verb or preposition in a clause where 'oneself' meaning 'me' or 'any person in general' refers to the same person as the subject of the verb.","ex":{"en":"One must apply oneself to the present and keep one's eyes firmly fixed on one's future goals","cn":"人们必须立足现在，目光锁定未来目标。"}},{"pos":"PRON-REFL 反身代词","cn":"（one 虽缺失但可理解为动词主语时，用作动词或介词的宾语）自己，自身","en":"Oneself can be used as the object of a verb or preposition, when 'one' is not present but is understood to be the subject of the verb.","ex":{"en":"The historic feeling of the town makes it a pleasant place to base oneself for summer vacations","cn":"该镇的历史气息让它成为人们夏季度假的好去处。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"独自；亲自；本人","en":"To do something oneself means to do it without any help from anyone else.","ex":{"en":"It is a very rewarding exercise to work this out oneself","cn":"独自解决这个问题是一次受益匪浅的锻炼。"}},{"pos":"PRON-REFL-EMPH 强调反身代词","cn":"（强调事情发生的对象）自己，自身","en":"You use oneself to emphasize that something happens to you rather than to people in general.","ex":{"en":"It is better to die oneself than to kill.","cn":"宁可自亡，不可行凶。"}}]},"examples":[{"en":"One has to ask oneself what the purpose of the exercise is.","cn":"大家必须问一问自己，这个锻炼的目的是什么。"},{"en":"One cannot choose freedom for oneself without choosing it for others.","cn":"人不能光为了自己的自由而不顾别人的自由。"}]},"onward":{"media":{"uk":"media/uk/onward__gb_1.mp3","us":"media/us/onward__us_1.mp3"},"oxford":{"phon":"ˈɒnwəd","pos":"adjective","senses":[{"en":"continuing or moving forward","cn":"继续的；向前的","ex":{"en":"Ticket prices include your flight and onward rail journey.","cn":"票价包括您的机票和接续的铁路旅费。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"向前的；前进的","en":"Onward means moving forward or continuing a journey.","ex":{"en":"British Airways have two flights a day to Bangkok, and there are onward flights to Phnom Penh.","cn":"英国航空公司每天有两个航班飞往曼谷，那里有前往金边的接续航班。"}},{"pos":"ADJ 形容词","cn":"发展的；进步的；日趋重要的","en":"Onward means developing, progressing, or becoming more important over a period of time.","ex":{"en":"...the onward march of progress in the British aircraft industry.","cn":"英国航空业的稳步发展"}},{"pos":"ADV 副词","cn":"（从某时起）一直","en":"If something happens from a particular time onwards or onward, it begins to happen at that time and continues to happen afterwards.","ex":{"en":"From the turn of the century onward, she shared the life of the aborigines.","cn":"她自世纪之交以来便同土著居民生活在一起。"}}]},"examples":[{"en":"Ticket prices include your flight and onward rail journey.","cn":"票价包括您的飞行航程和接续的铁路旅费。"},{"en":"The company offers flights to Amsterdam with onward travel to The Hague.","cn":"这家公司开设了飞往阿姆斯特丹并续飞海牙的航班。"}]},"only":{"media":{"uk":"media/uk/only__gb_1.mp3","us":"media/us/only__us_1.mp3"},"oxford":{"phon":"ˈəʊnli","pos":"adjective","senses":[{"en":"used to say that no other or others of the same group exist or are there","cn":"仅有的；唯一的","ex":{"en":"She's their only daughter.","cn":"她是他们的独生女。"}},{"en":"used to say that somebody/something is the best and you would not choose any other","cn":"最好的；最适当的","ex":{"en":"She's the only person for the job.","cn":"她是这项工作最合适的人选。"}},{"en":"nobody or nothing except","cn":"只；只有；仅","ex":{"en":"There are only a limited number of tickets available.","cn":"剩下的票数量很有限。"},"pos":"adverb"},{"en":"in no other situation, place, etc.","cn":"仅在…情况下（或地点等）","ex":{"en":"I agreed, but only because I was frightened.","cn":"我当时同意只是因为我很害怕。"},"pos":"adverb"},{"en":"no more important, interesting, serious, etc. than","cn":"只不过；仅…而已","ex":{"en":"It was only a suggestion.","cn":"这只是个提议罢了。"},"pos":"adverb"},{"en":"no more than; no longer than","cn":"只有；仅；刚刚","ex":{"en":"She's only 21 and she runs her own business.","cn":"她只有 21 岁，就经营起自己的企业了。"},"pos":"adverb"},{"en":"not until","cn":"（直到）…才；（只是）…才","lab":"formal","ex":{"en":"We only got here yesterday.","cn":"我们昨天才到这里。"},"pos":"adverb"},{"en":"used to say that somebody can do no more than what is mentioned, although this is probably not enough","cn":"仅此而已；只能","ex":{"en":"We can only guess what happened.","cn":"我们只能猜测发生了什么事。"},"pos":"adverb"},{"en":"used to say that something will have a bad effect","cn":"（用于说明事情的恶果）只会，愈加","ex":{"en":"If you do that, it will only make matters worse.","cn":"如果你那样做，只会乱上加乱。"},"pos":"adverb"},{"en":"used to mention something that happens immediately afterwards, especially something that is surprising, disappointing, etc.","cn":"不料；竟然","ex":{"en":"She turned up the driveway, only to find her way blocked.","cn":"她开上自家车道，不料发现路已被堵。"},"pos":"adverb"},{"en":"except that; but","cn":"不过；但是；可是","ex":{"en":"I'd love to come, only I have to work.","cn":"我很想去，但是我要上班。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"（表示比较而言唯一真实、恰当或必要的情况）只，只有","en":"You use only to indicate the one thing that is true, appropriate, or necessary in a particular situation, in contrast to all the other things that are not true, appropriate, or necessary.","ex":{"en":"Only the President could authorize the use of the atomic bomb","cn":"只有总统才能授权使用原子弹。"}},{"pos":"ADV 副词","cn":"（引出发生的必要条件）只有…（才）","en":"You use only to introduce the thing which must happen before the thing mentioned in the main part of the sentence can happen.","ex":{"en":"The lawyer is paid only if he wins","cn":"只有官司赢了才支付律师费。"}},{"pos":"ADJ 形容词","cn":"唯一的；仅有的","en":"If you talk about the only person or thing involved in a particular situation, you mean there are no others involved in it.","ex":{"en":"She was the only woman in Shell's legal department","cn":"她是壳牌公司法律事务部唯一的女性。"}},{"pos":"ADJ 形容词","cn":"（孩子）独生的,仅有的","en":"An only child is a child who has no brothers or sisters."},{"pos":"ADV 副词","cn":"(尤用于想要纠正错误观点时)只不过，仅…而已","en":"You use only to indicate that something is no more important, interesting, or difficult, for example, than you say it is, especially when you want to correct a wrong idea that someone may get or has already got.","ex":{"en":"At the moment it is only a theory","cn":"眼下这只不过是个推测而已。"}},{"pos":"ADV 副词","cn":"（强调数量少或时间短）才，仅仅","en":"You use only to emphasize how small an amount is or how short a length of time is.","ex":{"en":"Child car seats only cost about £10 a week to hire.","cn":"儿童汽车坐椅一周的租金才10英镑。"}},{"pos":"ADV 副词","cn":"（强调是其中的一小部分，而非全部）只，仅仅","en":"You use only to emphasize that you are talking about a small part of an amount or group, not the whole of it.","ex":{"en":"These are only a few of the possibilities","cn":"这些仅仅是其中几种可能。"}},{"pos":"ADV 副词","cn":"（用于 can 或 could 之后，强调除此以外别无可为）只（能）","en":"Only is used after 'can' or 'could' to emphasize that it is impossible to do anything except the rather inadequate or limited action that is mentioned.","ex":{"en":"For a moment I could say nothing. I could only stand and look","cn":"我有那么一会儿一句话都说不出来，只能站在那里看着。"}},{"pos":"ADV 副词","cn":"（强调希望或愿望）唯有，非常","en":"You can use only in the expressions I only wish or I only hope in order to emphasize what you are hoping or wishing.","ex":{"en":"I only wish he were here now that things are getting better for me","cn":"现在我的境况好转了，我真希望他能在这里。"}},{"pos":"CONJ-SUBORD 连词","cn":"（用于表示稍加改动或限定）只是，不过","en":"Only can be used to add a comment which slightly changes or limits what you have just said.","ex":{"en":"It's just as dramatic as a film, only it's real","cn":"这就像电影一样充满戏剧性，不过这是真实发生的。"}},{"pos":"CONJ-SUBORD 连词","cn":"（用于含有 would 的从句后，引出未做某事的原因）要不是，若非","en":"Only can be used after a clause with 'would' to indicate why something is not done.","ex":{"en":"I'd invite you to come with me, only it's such a long way","cn":"要不是路太远，我一定会邀你一同前往。"}},{"pos":"ADV 副词","cn":"（用于不定式前）不料，结果却","en":"You can use only before an infinitive to introduce an event which happens immediately after one you have just mentioned, and which is rather surprising or unfortunate.","ex":{"en":"Ryle tried the Embassy, only to be told that Hugh was in a meeting","cn":"赖尔试着找了大使馆，却被告知休正在开会。"}},{"pos":"ADV 副词","cn":"（强调行动或行为恰当）完全，真正","en":"You can use only to emphasize how appropriate a certain course of action or type of behaviour is.","ex":{"en":"It's only fair to let her know that you intend to apply","cn":"告诉她你打算申请，这才算公平嘛。"}},{"pos":"ADV 副词","cn":"（用于动词前，表示结果令人遗憾或不受欢迎）愈加，只（会）","en":"You can use only in front of a verb to indicate that the result of something is unfortunate or undesirable and is likely to make the situation worse rather than better.","ex":{"en":"The embargo would only hurt innocent civilians","cn":"禁运只会殃及无辜的百姓。"}},{"pos":"PHRASE 短语","cn":"只要（做…）即可","en":"If you say you only have to or have only to do one thing in order to achieve or prove a second thing, you are emphasizing how easily the second thing can be achieved or proved.","ex":{"en":"Any time you want a babysitter, dear, you only have to ask","cn":"亲爱的，你什么时候需要人帮忙照看孩子，只要开口说一声就行。"}},{"pos":"PHRASE 短语","cn":"刚才；刚刚","en":"You can say that something has only just happened when you want to emphasize that it happened a very short time ago.","ex":{"en":"I've only just arrived","cn":"我刚到。"}},{"pos":"PHRASE 短语","cn":"仅仅；勉强","en":"You use only just to emphasize that something is true, but by such a small degree that it is almost not true at all.","ex":{"en":"For centuries farmers there have only just managed to survive","cn":"几个世纪以来，那里的农民只能勉强维持生计。"}},{"pos":"PHRASE 短语","cn":"太；极","en":"You can use only too to emphasize that something is true or exists to a much greater extent than you would expect or like.","ex":{"en":"I know only too well that plans can easily go wrong","cn":"计划很容易出岔子，我太清楚这点了。"}},{"pos":"PHRASE 短语","cn":"（强调乐意）极，非常","en":"You can say that you are only too happy to do something to emphasize how willing you are to do it.","ex":{"en":"I'll be only too pleased to help them out with any queries.","cn":"我非常乐意为他们答疑解惑。"}},{"pos":"","cn":"","en":"if only→see: ; not only→see: ; the one and only→see: ;"}]},"examples":[{"en":"Children can be difficult as we know only too well.","cn":"小孩子往往很难对付，对此我们都非常清楚。"},{"en":"She's only 21 and she runs her own business.","cn":"她只有 21 岁就经营起自己的企业了。"}]},"once":{"media":{"uk":"media/uk/once__gb_1.mp3","us":"media/us/once__us_1.mp3"},"oxford":{"phon":"wʌns","pos":"adverb","senses":[{"en":"on one occasion only; one time","cn":"仅一次；一次","lab":"informal","ex":{"en":"I've only been there once.","cn":"我只去过那里一次。"}},{"en":"at some time in the past","cn":"曾；曾经","ex":{"en":"I once met your mother.","cn":"我曾经见过你母亲。"}},{"en":"used in negative sentences and questions, and after if to mean ‘ever’ or ‘at all’","cn":"（用于否定句、疑问句和 if 后）曾，根本","ex":{"en":"He never once offered to help.","cn":"他从没有主动提出过帮忙。"}},{"en":"used with a preposition or another adverb to mean ‘as soon as somebody/something is/was’","cn":"一旦…（就…）；一…（就…）","ex":{"en":"Once inside the gate, Sam hurried up the path.","cn":"一进大门，萨姆就沿着小路匆匆而上。"}},{"en":"as soon as; when","cn":"一…就；一旦；当…时候","ex":{"en":"We didn't know how we would cope once the money had gone.","cn":"一旦钱花光了，我们就不知道该怎么办了。"},"pos":"conjunction"}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"一次；一回","en":"If something happens once, it happens one time only.","ex":{"en":"I met Wilma once, briefly","cn":"我曾经和威尔玛有过短短的一面之缘。"}},{"pos":"ADV 副词","cn":"（与后接day, week, month等的a连用）（每…）一次，（每…）一回","en":"You use once with 'a' and words like 'day', 'week', and 'month' to indicate that something happens regularly, one time in each day, week, or month.","ex":{"en":"Lung cells die and are replaced about once a week","cn":"肺细胞约每周新老更替一次。"}},{"pos":"ADV 副词","cn":"（与后接day, week, year等的every连用）（每隔…）一次，（每隔…）一回","en":"You use once with 'every' and words like 'day', 'week', and 'year' to indicate that something happens a specified number of times and on a regular basis.","ex":{"en":"The patient was seen for follow-up visits once every three months","cn":"这位病人每三个月接受一次随访就诊。"}},{"pos":"ADV 副词","cn":"曾经，一度（状况如此）","en":"If something was once true, it was true at some time in the past, but is no longer true.","ex":{"en":"The culture minister once ran a theatre","cn":"这位文化部长曾经经营过一家剧院。"}},{"pos":"ADV 副词","cn":"曾经（做过某事）","en":"If someone once did something, they did it at some time in the past.","ex":{"en":"I once went camping at Lake Darling with a friend","cn":"我曾和一位朋友在达令湖畔露营。"}},{"pos":"CONJ-SUBORD 连词","cn":"一旦…（就…); 一…（就…）","en":"If something happens once another thing has happened, it happens immediately afterwards.","ex":{"en":"The decision had taken about 10 seconds once he'd read a market research study","cn":"在他看过一份市场调研报告后大概10秒钟就作出了决定。"}},{"pos":"PHRASE 短语","cn":"突然；忽然","en":"If something happens all at once, it happens suddenly, often when you are not expecting it to happen.","ex":{"en":"I feel terribly sleepy all at once","cn":"我突然觉得特别困。"}},{"pos":"PHRASE 短语","cn":"立即；马上","en":"If you do something at once, you do it immediately.","ex":{"en":"I have to go, I really must, at once","cn":"我得走了，我真的必须马上就走。"}},{"pos":"PHRASE 短语","cn":"同时；一起","en":"If a number of different things happen at once or all at once, they all happen at the same time.","ex":{"en":"You can't be doing two things at once","cn":"不能一心二用。"}},{"pos":"PHRASE 短语","cn":"就此一次；破例一次","en":"For once is used to emphasize that something happens on this particular occasion, especially if it has never happened before, and may never happen again.","ex":{"en":"For once, dad is not complaining","cn":"爸爸这次破天荒地没有抱怨。"}},{"pos":"PHRASE 短语","cn":"又一次；再次","en":"If something happens once again or once more, it happens again.","ex":{"en":"Amy picked up the hairbrush and smoothed her hair once more","cn":"埃米拿起发梳，再次将头发梳理整齐。"}},{"pos":"PHRASE 短语","cn":"彻底地；一劳永逸地","en":"If something happens once and for all, it happens completely or finally.","ex":{"en":"We have to resolve this matter once and for all","cn":"我们必须彻底解决这一问题。"}},{"pos":"PHRASE 短语","cn":"偶尔；间或","en":"If something happens once in a while, it happens sometimes, but not very often.","ex":{"en":"Earrings need to be taken out and cleaned once in a while.","cn":"耳环要偶尔取出来清洗一下。"}},{"pos":"PHRASE 短语","cn":"一两次；几次","en":"If you have done something once or twice, you have done it a few times, but not very often.","ex":{"en":"I popped my head round the door once or twice","cn":"我有几次头撞到了门上。"}},{"pos":"PHRASE 短语","cn":"（常用于儿童故事的开头）从前，很久以前","en":"Once upon a time is used to indicate that something happened or existed a long time ago or in an imaginary world. It is often used at the beginning of children's stories.","ex":{"en":"'Once upon a time,' he began, 'there was a man who had everything.'","cn":"“很久很久以前，”他开始说道，“有这么一个人，他应有尽有。”"}},{"pos":"","cn":"","en":"once in a blue moon→see: ;"}]},"examples":[{"en":"If she once decides to do something, you won't change her mind.","cn":"她一旦决定干什么，谁也改变不了她的主意。"},{"en":"We didn't know how we would cope once the money had gone.","cn":"一旦钱花光了，我们就不知道该怎么办了。"}]},"one's":{"media":{"uk":"media/uk/one_s_1_gb_1.mp3","us":"media/us/one_s_1_us_1.mp3"},"oxford":{"phon":"wʌnz","pos":"det.","senses":[{"en":"the possessive form of one （one","cn":"的所有格）个人的，自己的"}]},"collins":{"senses":[{"pos":"DET-POSS 所有格限定词","cn":"人们的；自己的","en":"Speakers and writers use one's to indicate that something belongs or relates to people in general, or to themselves in particular.","ex":{"en":"...a feeling of responsibility for the welfare of others in one's community","cn":"为社群的其他成员谋福利的责任感"}},{"pos":"","cn":"（one is 或尤当 has 为助动词时 one has 的一种口语形式）","en":"One's can be used as a spoken form of 'one is' or 'one has', especially when 'has' is an auxiliary verb. →see: ;","ex":{"en":"No one's going to hurt you. No one. Not any more","cn":"没有人会伤害你了，不会有人了，再也不会有了。"}}]},"examples":[{"en":"One tries one's best.","cn":"一个人尽其所能。"}]},"onto":{"media":{"uk":"media/uk/onto__gb_1.mp3","us":"media/us/onto__us_1.mp3"},"oxford":{"phon":"ˈɒntə","pos":"preposition","senses":[{"en":"used with verbs to express movement on or to a particular place or position","cn":"（与动词连用，表示朝某处或某位置运动）向，朝","ex":{"en":"Move the books onto the second shelf.","cn":"把书移到第二层架子上。"}},{"en":"used to show that something faces in a particular direction","cn":"朝向，面向（某个方向）","ex":{"en":"The window looked out onto the terrace.","cn":"窗户外对着的是露天平台。"}}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"到…之上；向…之上","en":"If something moves or is put onto an object or surface, it is then on that object or surface.","ex":{"en":"I took my bags inside, lowered myself onto the bed and switched on the TV","cn":"我把包拎进屋，往床上一倒，然后打开了电视机。"}},{"pos":"PREP 介词","cn":"到（某处）","en":"You can sometimes use onto to mention the place or area that someone moves into.","ex":{"en":"The players emerged onto the field","cn":"运动员入场了。"}},{"pos":"PREP 介词","cn":"（光线或视线）朝向,转向","en":"You can use onto to introduce the place towards which a light or someone's look is directed.","ex":{"en":"...the metal part of the door onto which the sun had been shining","cn":"在阳光照耀下闪闪发亮的门的金属部分"}},{"pos":"PREP 介词","cn":"通向（某处）","en":"You can use onto to introduce a place that you would immediately come to after leaving another place that you have just mentioned, because they are next to each other.","ex":{"en":"...windows opening onto carved black-wood balconies","cn":"开向黑檀雕花阳台的窗户"}},{"pos":"PREP 介词","cn":"（重心移动）到（身体某部位）上","en":"When you change the position of your body, you use onto to introduce the part your body which is now supporting you.","ex":{"en":"As he stepped backwards she fell onto her knees, then onto her face","cn":"他向后退时，她双膝跪倒在地，接着迎面倒了下去。"}},{"pos":"PREP 介词","cn":"到（交通工具）上","en":"When you get onto a bus, train, or plane, you enter it in order to travel somewhere.","ex":{"en":"As he got on to the plane, he asked me how I was feeling","cn":"他上飞机时问我感觉如何。"}},{"pos":"PREP 介词","cn":"（用于 hold，hang，cling 等动词后，表示抓紧或牢牢固定）在…上","en":"Onto is used after verbs such as 'hold', 'hang', and 'cling' to indicate what someone is holding firmly or where something is being held firmly.","ex":{"en":"The reflector is held onto the sides of the spacecraft with a frame","cn":"反射器通过支架牢牢地固定在航天器的侧面。"}},{"pos":"PREP 介词","cn":"转到（其他话题）","en":"If people who are talking get onto a different subject, they begin talking about it.","ex":{"en":"Let's get on to more important matters","cn":"咱们谈谈更重要的事吧。"}},{"pos":"PREP 介词","cn":"成为（列表、系统等）的一部分","en":"You can sometimes use onto to indicate that something or someone becomes included as a part of a list or system.","ex":{"en":"The Macedonian question had failed to get on to the agenda","cn":"马其顿问题没能列入议事日程。"}},{"pos":"PREP 介词","cn":"即将发现（重要之事）","en":"If someone is onto something, they are about to discover something important.","ex":{"en":"He leaned across the table and whispered to me, 'I'm really onto something.'","cn":"他从桌上俯过身来对我低声说道：“我真的就快有重大发现了。”"}},{"pos":"PREP 介词","cn":"发现（某人做坏事）；对…觉察；对…知悉","en":"If someone is onto you, they have discovered that you are doing something illegal or wrong.","ex":{"en":"He did not want Pollard to become suspicious that he was now onto him","cn":"他不想让波拉德怀疑他已察觉到其不轨行为。"}}]},"examples":[{"en":"They've been onto me for ages to get a job.","cn":"很久以来，他们一直催促我找份工作。"},{"en":"Scientists believe they are onto something big.","cn":"科学家相信，他们将会有重大发现。"}]},"on":{"media":{"uk":"media/uk/on__gb_1.mp3","us":"media/us/on__us_1.mp3"},"oxford":{"phon":"ɒn","pos":"preposition","senses":[{"en":"in or into a position covering, touching or forming part of a surface","cn":"（覆盖、附着）在…上（意指接触物体表面或构成物体表面的一部分）","ex":{"en":"a picture on a wall","cn":"墙上的画"}},{"en":"supported by somebody/something","cn":"由…支撑着","ex":{"en":"She was standing on one foot.","cn":"她单脚站立着。"}},{"en":"used to show a means of transport","cn":"在（交通工具）上","ex":{"en":"He was on the plane from New York.","cn":"他在从纽约来的飞机上。"}},{"en":"by means of something; using something","cn":"通过；使用；借助于","ex":{"en":"She played a tune on her guitar.","cn":"她用她的吉他弹了一支曲子。"}},{"en":"used to show a day or date","cn":"在（某一天）","ex":{"en":"He came on Sunday.","cn":"他是星期天来的。"}},{"en":"used to describe an activity or a state","cn":"（用于说明活动或状态）","ex":{"en":"to be on business/holiday/vacation","cn":"在工作／度假中"}},{"en":"used to show direction","cn":"（表示方向）在，向，对","ex":{"en":"on the left/right","cn":"在左边／右边"}},{"en":"at or near a place","cn":"在，接近（某地）","ex":{"en":"a town on the coast","cn":"沿海的城镇"}},{"en":"used to show the basis or reason for something","cn":"根据；由于","ex":{"en":"a story based on fact","cn":"基于事实的小说"}},{"en":"immediately after something","cn":"就在…之后；一…就","ex":{"en":"On arriving home I discovered they had gone.","cn":"我一到家就发现他们已经离开了。"}},{"en":"about something/somebody","cn":"关于（事或人）","ex":{"en":"a book on South Africa","cn":"一本关于南非的书"}},{"en":"used to show that somebody belongs to a group or an organization","cn":"为（某团体或组织）的一员","ex":{"en":"to be on the committee/staff/jury/panel","cn":"为委员会／全体职员／陪审团／专家组的成员"}},{"en":"eating or drinking something; using a drug or a medicine regularly","cn":"吃；喝；按时服用（药物）","ex":{"en":"He lived on a diet of junk food.","cn":"他把垃圾食品当饭吃。"}},{"en":"paid for by something","cn":"以…支付；由…支付","ex":{"en":"to live on a pension/a student grant","cn":"靠养老金／助学金生活"}},{"en":"used when giving a phone number","cn":"（提供电话号码时用）","ex":{"en":"You can get me on 020 7946 0887.","cn":"你找我可以拨打 020 7946 0887。"}},{"en":"used with some nouns or adjectives to say who or what is affected by something","cn":"（与某些名词或形容词连用，表示影响到）","ex":{"en":"a ban on smoking","cn":"对吸烟的禁令"}},{"en":"being carried by somebody; in the possession of somebody","cn":"（身上）带着；有","ex":{"en":"Have you got any money on you?","cn":"你带钱了没有？"}},{"en":"compared with somebody/something","cn":"与…相比","ex":{"en":"Sales are up on last year.","cn":"销售量比去年增长了。"}},{"en":"on somebody’s body; being worn","cn":"穿在身上；穿着；戴着","ex":{"en":"Put your coat on.","cn":"把外衣穿上。"},"pos":"adverb"},{"en":"covering, touching or forming part of something","cn":"（表示覆盖、接触某物或成为某物的一部分）","ex":{"en":"Make sure the lid is on.","cn":"要注意盖上盖子。"},"pos":"adverb"},{"en":"in or into a vehicle","cn":"登上（车辆）","ex":{"en":"The bus stopped and four people got on.","cn":"公共汽车停下来，四个人上了车。"},"pos":"adverb"},{"en":"connected or operating; being used","cn":"（表示已连接、处于工作状态或使用中）","ex":{"en":"The lights were all on.","cn":"灯都亮着。"},"pos":"adverb"},{"en":"used to show that somebody/something moves or is sent forward","cn":"向前（移动）","ex":{"en":"She stopped for a moment, then walked on.","cn":"她停了一会儿，然后又向前走。"},"pos":"adverb"},{"en":"used to show that something continues","cn":"（表示持续性）","ex":{"en":"He worked on without a break.","cn":"他毫不停歇地继续工作。"},"pos":"adverb"},{"en":"happening","cn":"（表示发生）","ex":{"en":"There was a war on at the time.","cn":"当时正值战争。"},"pos":"adverb"},{"en":"planned to take place in the future","cn":"（预先安排的事）将发生","ex":{"en":"The game is still on (= it has not been cancelled).","cn":"比赛仍将举行。"},"pos":"adverb"},{"en":"on duty; working","cn":"值班；执行任务中","ex":{"en":"I'm on now till 8 tomorrow morning.","cn":"我正在值班，要值到明早 8 点钟。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"PREP 介词","cn":"（表示支承）在…上","en":"If someone or something is on a surface or object, the surface or object is immediately below them and is supporting their weight.","ex":{"en":"He is sitting beside her on the sofa","cn":"他挨着她坐在沙发上。"}},{"pos":"PREP 介词","cn":"（表示粘贴或附着）在…上","en":"If something is on a surface or object, it is stuck to it or attached to it.","ex":{"en":"I admired the peeling paint on the ceiling","cn":"我“观赏”着天花板上正在剥落的油漆。"}},{"pos":"PREP 介词","cn":"（放、扔或掉）在…上面","en":"If you put, throw, or drop something on a surface, you move it or drop it so that it is then supported by the surface.","ex":{"en":"He got his winter jacket from the closet and dropped it on the sofa","cn":"他从衣橱里取出冬天穿的夹克，把它扔到沙发上。"}},{"pos":"PREP 介词","cn":"（身体重量）由（某部位）支撑","en":"You use on to say what part of your body is supporting your weight.","ex":{"en":"He continued to lie on his back and look at clouds","cn":"他仍旧仰卧着，望着天上的云彩。"}},{"pos":"PREP 介词","cn":"（表示接触到身体某部位）在…上","en":"You use on to say that someone or something touches a part of a person's body.","ex":{"en":"He leaned down and kissed her lightly on the mouth","cn":"他俯下身去，在她嘴唇上轻轻一吻。"}},{"pos":"PREP 介词","cn":"（某种表情）在（脸）上","en":"If someone has a particular expression on their face, their face has that expression.","ex":{"en":"The maid looked at him, a nervous smile on her face","cn":"女服务员看着他，脸上带着一丝局促不安的微笑。"}},{"pos":"ADV 副词","cn":"（穿或戴）上，在身上","en":"When you put a piece of clothing on, you place it over part of your body in order to wear it. If you have it on, you are wearing it.","ex":{"en":"He put his coat on while she opened the front door","cn":"她打开前门时，他穿上了大衣。"}},{"pos":"PREP 介词","cn":"带在…身上","en":"You can say that you have something on you if you are carrying it in your pocket or in a bag.","ex":{"en":"I didn't have any money on me","cn":"我身上一分钱也没有。"}},{"pos":"PREP 介词","cn":"（视线）落在…身上","en":"If someone's eyes are on you, they are looking or staring at you.","ex":{"en":"Everyone's eyes were fixed on him","cn":"每个人都盯着他看。"}},{"pos":"PREP 介词","cn":"（碰）上…（而受伤）","en":"If you hurt yourself on something, you accidentally hit a part of your body against it and that thing causes damage to you.","ex":{"en":"Mr Pendle hit his head on a wall as he fell","cn":"彭德尔先生摔倒时头磕到了墙上。"}},{"pos":"PREP 介词","cn":"在（某）地","en":"If you are on an area of land, you are there.","ex":{"en":"He was able to spend only a few days at a time on the island","cn":"他每次去岛上都只能呆几天。"}},{"pos":"PREP 介词","cn":"是（道路、海岸等）的一部分；在…边上","en":"If something is situated on a place such as a road or coast, it forms part of it or is by the side of it.","ex":{"en":"Bergdorf Goodman has opened a men's store on Fifth Avenue","cn":"波道夫·古德曼在第五大道上开了一家男装店。"}},{"pos":"PREP 介词","cn":"上，乘（公共汽车、火车或飞机）","en":"If you get on a bus, train, or plane, you go into it in order to travel somewhere. If you are on it, you are travelling in it.","ex":{"en":"We waited till twelve and we finally got on the plane","cn":"我们一直等到12点才终于上了飞机。"}},{"pos":"PREP 介词","cn":"（写或印刷）在…上","en":"If there is something on a piece of paper, it has been written or printed there.","ex":{"en":"The writing on the back of the card was cramped but scrupulously neat","cn":"这张卡片的背面写满了密密麻麻但却十分工整的字。"}},{"pos":"PREP 介词","cn":"在（名单）上；包括在…内","en":"If something is on a list, it is included in it.","ex":{"en":"I've seen your name on the list of deportees","cn":"我看见你的名字在被驱逐出境者名单之列。"}},{"pos":"PREP 介词","cn":"（书、讨论或观点）关于，涉及","en":"Books, discussions, or ideas on a particular subject are concerned with that subject.","ex":{"en":"The longest chapter in almost any book on baby care is on feeding","cn":"几乎所有关于婴儿护理的书籍中内容最多的一章都是喂养。"}},{"pos":"PREP 介词","cn":"以，凭，靠（某一方法、原则或系统）","en":"You use on to introduce the method, principle, or system which is used to do something.","ex":{"en":"...a television that we bought on credit two months ago.","cn":"我们两个月前赊购的电视机"}},{"pos":"PREP 介词","cn":"通过，借助于（某一器械或机器）","en":"If something is done on an instrument or a machine, it is done using that instrument or machine.","ex":{"en":"...songs that I could just sit down and play on the piano","cn":"我坐下来就可以在钢琴上弹出的歌曲"}},{"pos":"PREP 介词","cn":"以…方式（储存信息）","en":"If information is, for example, on tape or on computer, that is the way that it is stored.","ex":{"en":"'I thought it was a load of rubbish.' — 'Right we've got that on tape.'","cn":"“我觉得那是一派胡言。”——“没错，我们已经把它录在磁带上了。”"}},{"pos":"PREP 介词","cn":"在（广播或电视）上播出","en":"If something is being broadcast, you can say that it is on the radio or television.","ex":{"en":"Every sporting event on television and satellite over the next seven days is listed","cn":"未来7天通过电视和卫星转播的每一项体育赛事都列在节目预告单上。"}},{"pos":"ADJ 形容词","cn":"正在发生的","en":"When an activity is taking place, you can say that it is on .","ex":{"en":"There's a marvellous match on at Wimbledon at the moment","cn":"此刻在温布尔登正进行着一场精彩的比赛。"}},{"pos":"ADV 副词","cn":"（表示某人忙碌程度）忙得很/没什么可忙","en":"You use on in expressions such as 'have a lot on' and 'not have very much on' to indicate how busy someone is.","ex":{"en":"I have a lot on in the next week.","cn":"我下周特别忙。"}},{"pos":"PREP 介词","cn":"（引出所进行的活动，特别是旅行）处于…情况中，在从事…中","en":"You use on to introduce an activity that someone is doing, particularly travelling.","ex":{"en":"I've always wanted to go on a cruise","cn":"我一直想坐游轮旅游。"}},{"pos":"ADV 副词","cn":"（机器、电灯等）开着，工作着，使用中","en":"When something such as a machine or an electric light is on, it is functioning or in use. When you switch it on, it starts functioning.","ex":{"en":"The light was on and the door was open","cn":"灯亮着，门也敞开着。"}},{"pos":"PREP 介词","cn":"是…的成员；供职于","en":"If you are on a committee or council, you are a member of it.","ex":{"en":"Claire and Beryl were on the organizing committee","cn":"克莱尔和贝丽尔是组委会成员。"}},{"pos":"PREP 介词","cn":"在（某一日子或日期）（发生）","en":"You can indicate when something happens by saying that it happens on a particular day or date.","ex":{"en":"This year's event will take place on June 19th, a week earlier than usual","cn":"今年的活动将于6月19日举行，比往年提前一周。"}},{"pos":"PREP 介词","cn":"在…后立即；一…就","en":"You use on when mentioning an event that was followed by another one.","ex":{"en":"She waited in her hotel to welcome her children on their arrival from London","cn":"她在宾馆里等候，准备第一时间迎接孩子们从伦敦过来。"}},{"pos":"ADV 副词","cn":"（继续）下去","en":"You use on to say that someone is continuing to do something.","ex":{"en":"They walked on in silence for a while","cn":"他们继续默默无语地走了一会儿。"}},{"pos":"ADV 副词","cn":"不停地（数落、抱怨、纠缠）","en":"If you say that someone goes on at you, you mean that they continually criticize you, complain to you, or ask you to do something.","ex":{"en":"She's been on at me for weeks to show her round the stables","cn":"她缠了我好几个星期了，要我带她去马厩看看。"}},{"pos":"ADV 副词","cn":"从…时候起；自…以后","en":"You use on in expressions such as from now on and from then on to indicate that something starts to happen at the time mentioned and continues to happen afterwards.","ex":{"en":"Perhaps it would be best not to see much of you from now on","cn":"也许从现在起我们最好少见面。"}},{"pos":"ADV 副词","cn":"（常用在副词early，late，far及其比较级之后，尤置于句首、句尾或介词之前）","en":"You often use on after the adverbs 'early', 'late', 'far', and their comparative forms, especially at the beginning or end of a sentence, or before a preposition.","ex":{"en":"The market square is a riot of colour and animation from early on in the morning","cn":"从大清早起这个市集广场就色彩缤纷，生机勃勃。"}},{"pos":"PREP 介词","cn":"定期服用；服…成瘾","en":"Someone who is on a drug takes it regularly.","ex":{"en":"She was on antibiotics for an eye infection that wouldn't go away","cn":"由于眼睛感染一直不见好，她在服用抗生素。"}},{"pos":"PREP 介词","cn":"以…（为食）；（机器）用（某种动力或燃料运转）","en":"If you live on a particular kind of food, you eat it. If a machine runs on a particular kind of power or fuel, it uses it in order to function.","ex":{"en":"The caterpillars feed on a wide range of trees, shrubs and plants","cn":"毛虫以各类树木、灌木和植物为食。"}},{"pos":"PREP 介词","cn":"以…（为收入）","en":"If you are on a particular income, that is the income that you have.","ex":{"en":"...young people who are unemployed or on low wages","cn":"失业或低收入的年轻人"}},{"pos":"PREP 介词","cn":"（税收或利润）获自…，来自…","en":"Taxes or profits that are obtained from something are referred to as taxes or profits on it.","ex":{"en":"...a general strike to protest a tax on food and medicine last week","cn":"上周抗议对食品和药品征税的大罢工"}},{"pos":"PREP 介词","cn":"在…方面（花钱）","en":"When you buy something or pay for something, you spend money on it.","ex":{"en":"I resolved not to waste money on a hotel","cn":"我决心不在住旅馆方面浪费钱。"}},{"pos":"PREP 介词","cn":"在…方面（花时间或精力）","en":"When you spend time or energy on a particular activity, you spend time or energy doing it.","ex":{"en":"People complain about how children spend so much time on computer games","cn":"人们常抱怨孩子花太多时间玩电脑游戏。"}},{"pos":"PHRASE 短语","cn":"无法接受的；行不通的","en":"If you say that something is not on or is just not on, you mean that it is unacceptable or impossible.","ex":{"en":"I'm not having children who don't like cheese. It's not on","cn":"我可不要不爱吃奶酪的孩子，那可不行。"}},{"pos":"PHRASE 短语","cn":"不停地；继续不断地","en":"If you say that something happens on and on, you mean that it continues to happen for a very long time.","ex":{"en":"...designers, builders, fitters — the list goes on and on","cn":"设计师、建筑工人、装配工——这个单子可以没完没了"}},{"pos":"PHRASE 短语","cn":"（表示困惑）在谈论什么","en":"If you ask someone what they are on about or what they are going on about, you are puzzled because you cannot understand what they are talking about.","ex":{"en":"What on earth are you going on about?","cn":"你到底在说些什么呀？"}},{"pos":"PHRASE 短语","cn":"（表示有信心）知道自己在说些什么，了解情况","en":"If you say that someone knows what they are on about, you are confident that what they are saying is true or makes sense, for example because they are an expert.","ex":{"en":"It looks like he knows what he's on about.","cn":"他看起来很在行。"}},{"pos":"PHRASE 短语","cn":"掌握不利于（某人）的证据；抓住（某人）的把柄","en":"If someone has something on you, they have evidence that you have done something wrong or bad. If they have nothing on you, they cannot prove that you have done anything wrong or bad.","ex":{"en":"He may have something on her. He may have supplied her with drugs, and then threatened to tell if she didn't do this","cn":"他或许抓住了她的什么把柄。可能是给她提供了毒品，然后威胁她如果不这样做的话就告发她。"}},{"pos":"","cn":"","en":"on behalf of→see: ; on and off→see: ; and so on→see: ; on top of→see: ;"}]},"examples":[{"en":"You can get me on 020 7946 0887.","cn":"你找我可以拨打 020 7946 0887。"},{"en":"I didn't know what he was on about. It didn't make sense.","cn":"我不知道他说的是什么，他说得不清不楚的。"}]},"online":{"media":{"uk":"media/uk/online__gb_1.mp3","us":"media/us/online__us_1.mp3"},"oxford":{"phon":"ˌɒnˈlaɪn","pos":"adjective","senses":[{"en":"available on or done using the internet or other computer network","cn":"线上的；网上的","ex":{"en":"Online shopping is both cheap and convenient.","cn":"网上购物既便宜又方便。"}},{"en":"connected to the internet; able to connect to the internet","cn":"联网的；可上网的","ex":{"en":"You can see which of your friends are online and send them messages.","cn":"你可以查看哪些朋友在线并给他们发讯息。"}},{"en":"onto the internet; using the internet or other computer network","cn":"在网上；利用网络","ex":{"en":"Many children would rather go online than watch television.","cn":"许多孩子宁愿上网也不看电视。"},"pos":"adverb"},{"en":"in or into operation or existence","cn":"在运行；开始运作；投入使用","ex":{"en":"The new system will go online this month.","cn":"新系统将于本月开始运行。"},"pos":"adverb"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"（公司服务）网上开通的，网上经营的","en":"If a company goes online, its services become available on the Internet.","ex":{"en":"...the first bank to go online.","cn":"第一家开通网上业务的银行"}},{"pos":"ADJ 形容词","cn":"联机的；在线的","en":"If you are online, your computer is connected to the Internet. →see: ;","ex":{"en":"You can chat to other people who are online.","cn":"你可以和其他在线的人聊天。"}}]},"examples":[{"en":"The majority of small businesses now do their banking online.","cn":"大多数小企业现在都在网上办理银行业务。"},{"en":"Online shopping is both cheap and convenient.","cn":"网上购物既便宜又方便。"}]},"onset":{"media":{"uk":"media/uk/onset__gb_1.mp3","us":"media/us/onset__us_1.mp3"},"oxford":{"phon":"ˈɒnset","pos":"noun","senses":[{"en":"the beginning of something, especially something unpleasant","cn":"开端，发生，肇始（尤指不快的事件）","ex":{"en":"the onset of disease/old age/winter","cn":"疾病的发作；老年的开始；冬天的来临"}}]},"collins":{"senses":[{"pos":"N-SING 单数名词","cn":"（尤指不快之事的）开始，开端，肇始","en":"The onset of something is the beginning of it, used especially to refer to something unpleasant.","ex":{"en":"Most of the passes have been closed with the onset of winter","cn":"冬天来临，大部分关口均已关闭。"}}]},"examples":[{"en":"the onset of disease/old age/winter","cn":"疾病的发作；老年的开始；冬天的来临"},{"en":"the onset of winter","cn":"冬天的来临"}]},"one":{"media":{"uk":"media/uk/one__gb_1.mp3","us":"media/us/one__us_1.mp3"},"oxford":{"phon":"wʌn","pos":"number, determiner","senses":[{"en":"the number 1","cn":"一","ex":{"en":"Do you want one or two?","cn":"你要一个还是两个？"}},{"en":"used in formal language or for emphasis before hundred, thousand, etc., or before a unit of measurement","cn":"（正式用语或表示强调，用在 hundred、thousand 等或度量单位之前）一","ex":{"en":"It cost one hundred and fifty pounds.","cn":"那东西花了一百五十英镑。"}},{"en":"used for emphasis to mean ‘a single’ or ‘just one’","cn":"（表示强调）单独一个，仅仅一个","ex":{"en":"There's only one thing we can do.","cn":"我们能做的只有一件事。"}},{"en":"a person or thing, especially when they are part of a group","cn":"（尤指一组中的）一个人，一件事物","ex":{"en":"One of my friends lives in Brighton.","cn":"我有一个朋友住在布赖顿。"}},{"en":"used for emphasis to mean ‘the only one’ or ‘the most important one’","cn":"（表示强调）唯一的一个，最重要的一个","ex":{"en":"He's the one person I can trust.","cn":"他是我唯一可以信赖的人。"}},{"en":"used when you are talking about a time in the past or the future, without actually saying which one","cn":"（用于一般地谈论过去或将来的某个时间）","ex":{"en":"I saw her one afternoon last week.","cn":"我在上周的一个下午见到了她。"}},{"en":"the same","cn":"同一个","ex":{"en":"They all went off in one direction.","cn":"他们都朝同一个方向走了。"}},{"en":"used for emphasis instead of a or an","cn":"（代替 a 或 an，表示强调）","lab":"informal, especially North American English，，","ex":{"en":"That was one hell of a game!","cn":"那一场比赛简直不得了！"}},{"en":"used with a person’s name to show that the speaker does not know the person","cn":"（与人名连用，表示说话人不认识的人）某一个","lab":"formal or old-fashioned","ex":{"en":"He worked as an assistant to one Mr Ming.","cn":"他给一位明先生当助手。"}},{"en":"used to avoid repeating a noun, when you are referring to somebody/something that has already been mentioned, or that the person you are speaking to knows about","cn":"（用来避免重复已提过的或是听者已知的事物的名称）","lab":"British English","ex":{"en":"I'd like an ice cream. Are you having one, too?","cn":"我想买份冰激凌，你也要一份吗？"},"pos":"pronoun"},{"en":"used when you are identifying the person or thing you are talking about","cn":"（用于辨别所谈的人或事）","ex":{"en":"Our house is the one next to the school.","cn":"我家的房子就是学校旁边的那座。"},"pos":"pronoun"},{"en":"a person or thing belonging to a particular group","cn":"其中的一个人（或事物）","ex":{"en":"It's a present for one of my children.","cn":"这是送给我的一个孩子的礼物。"},"pos":"pronoun"},{"en":"a person of the type mentioned","cn":"（某种类型的）人","ex":{"en":"10 o’clock is too late for the little ones.","cn":"十点钟对那些小家伙来说就太晚了。"},"pos":"pronoun"},{"en":"used to mean ‘people in general’ or ‘I’, when the speaker is referring to himself or herself","cn":"人们；本人","lab":"formal","ex":{"en":"One should never criticize if one is not sure of one's facts.","cn":"一个人如果对自己掌握的事实没有把握，就绝不该随便批评。"},"pos":"pronoun"},{"en":"a person whose behaviour is funny or surprising","cn":"（举止）滑稽可笑的人，令人惊奇的人","lab":"old-fashioned, especially British English，，","ex":{"en":"Oh, you are a one!","cn":"哈！你这个活宝！"},"pos":"pronoun"},{"en":"the joke","cn":"玩笑；笑话","ex":{"en":"Have you heard the one about the Englishman, the Irishman and the Scotsman?","cn":"你听没听过那个关于英格兰人、爱尔兰人和苏格兰人的笑话？"},"pos":"pronoun"}]},"collins":{"senses":[{"pos":"NUM 数词","cn":"（数字）1","en":"One is the number 1.","ex":{"en":"They had three sons and one daughter.","cn":"他们有3个儿子，1个女儿。"}},{"pos":"ADJ 形容词","cn":"唯一的；仅有的","en":"If you say that someone or something is the one person or thing of a particular kind, you are emphasizing that they are the only person or thing of that kind.","ex":{"en":"They had alienated the one man who knew the business","cn":"他们弄僵了同那个唯一懂行的人之间的关系。"}},{"pos":"DET 限定词","cn":"（用于代替a以强调之后的名词）","en":"One can be used instead of 'a' to emphasize the following noun.","ex":{"en":"There is one thing I would like to know—What is it about Tim that you find so irresistible?","cn":"有一件事我很想知道——蒂姆到底哪一点让你对他如此倾心？"}},{"pos":"DET 限定词","cn":"（用于代替a以强调之后的形容词或短语）","en":"You can use one instead of 'a' to emphasize the following adjective or expression.","ex":{"en":"If we ever get married we'll have one terrific wedding","cn":"如果我们哪一天结婚的话，一定会有一个棒极了的婚礼。"}},{"pos":"DET 限定词","cn":"（用于人名前，表示未曾相识或听闻的）某一个","en":"You can use one in front of someone's name to indicate that you have not met them or heard of them before.","ex":{"en":"It seems that the fifth man is one John Cairncross.","cn":"第五位好像是一个名叫约翰·凯恩克罗斯的人。"}},{"pos":"DET 限定词","cn":"（表示与其他的作比较）这一个","en":"You can use one to refer to the first of two or more things that you are comparing.","ex":{"en":"Prices vary from one shop to another","cn":"各家商店价格不同。"}},{"pos":"PRON 代词","cn":"（用于代替名词，指代某类明确的人或事物）","en":"You can use one or ones instead of a noun when it is clear what type of thing or person you are referring to and you are describing them or giving more information about them.","ex":{"en":"They are selling their house to move to a smaller one","cn":"他们正打算卖掉房子，然后搬到一个小一点的住处。"}},{"pos":"PRON 代词","cn":"（泛指）人们","en":"You use ones to refer to people in general.","ex":{"en":"We are the only ones who know.","cn":"我们是唯一的知情者。"}},{"pos":"PRON 代词","cn":"（用于代替名词词组，表示刚提到过的事物）","en":"You can use one instead of a noun group when you have just mentioned something and you want to describe it or give more information about it.","ex":{"en":"His response is one of anger and frustration","cn":"他的回答充满了愤怒和懊丧。"}},{"pos":"DET 限定词","cn":"（特指一群人或事物中的）一人，一个","en":"You can use one when you have been talking or writing about a group of people or things and you want to say something about a particular member of the group.","ex":{"en":"'A college degree isn't enough', said one honors student.","cn":"“光有一个大学学位还不够，”一位优等生说。"}},{"pos":"QUANT 数量词","cn":"（同类事物或人中）（最…之）一","en":"You use one in expressions such as 'one of the biggest airports' or 'one of the most experienced players' to indicate that something or someone is bigger or more experienced than most other things or people of the same kind.","ex":{"en":"Subaru is one of the smallest Japanese car makers.","cn":"斯巴鲁是日本最小的汽车制造商之一。"}},{"pos":"DET 限定词","cn":"（过去或将来的）某一（时刻）","en":"You can use one when referring to a time in the past or in the future. For example, if you say that you did something one day, you mean that you did it on a day in the past. one day→see: ;","ex":{"en":"How would you like to have dinner one night, just you and me?","cn":"哪天晚上一起吃饭怎么样？就咱俩。"}},{"pos":"PRON 代词","cn":"（指代问题、笑话、评论、讨论的主题等）一个","en":"You can use one to refer to a question, joke, remark, or subject of discussion.","ex":{"en":"This is a tricky one to answer","cn":"这是个难以回答的问题。"}},{"pos":"PRON 代词","cn":"(一杯)酒","en":"You can use one to refer to an alcoholic drink.","ex":{"en":"Other members of the committee drifted in for a quick one before closing time.","cn":"委员会的其他成员陆续走了进来，想要趁关门前喝上一杯。"}},{"pos":"PRON 代词","cn":"（泛指包括自己的人，可作句子的主语或宾语）一个人，任何人","en":"You use one to make statements about people in general which also apply to themselves. One can be used as the subject or object of a sentence.","ex":{"en":"If one looks at the longer run, a lot of positive things are happening","cn":"如果把目光放长远些，就会发现很多积极的事情正在发生。"}},{"pos":"PHRASE 短语","cn":"一起；一致地","en":"If a group of people does something as one, all the people do the same thing at the same time or in the same way.","ex":{"en":"The 40,000 crowd rose as one.","cn":"40,000人全体起立。"}},{"pos":"PHRASE 短语","cn":"喜欢（或赞成、乐于）…的人","en":"If you say that someone is one for or is a one for something, you mean that they like or approve of it or enjoy doing it.","ex":{"en":"I'm not one for political discussions","cn":"我不是个热衷于谈论政治的人。"}},{"pos":"PHRASE 短语","cn":"（强调某人与众不同的反应或行为方式）举个例说","en":"You can use for one to emphasize that a particular person is definitely reacting or behaving in a particular way, even if other people are not.","ex":{"en":"I, for one, hope you don't get the job.","cn":"就我而言，我并不希望你得到那份工作。"}},{"pos":"PHRASE 短语","cn":"（表示强调）很多","en":"You can use expressions such as a hundred and one ,a thousand and one, and a million and one to emphasize that you are talking about a large number of things or people.","ex":{"en":"There are a hundred and one ways in which you can raise money.","cn":"筹钱的办法有很多。"}},{"pos":"PHRASE 短语","cn":"集（若干部分或功能）为一体","en":"You can use in one to indicate that something is a single unit, but is made up of several different parts or has several different functions.","ex":{"en":"...a love story and an adventure all in one","cn":"集爱情和冒险于一体的故事"}},{"pos":"PHRASE 短语","cn":"三三两两地；零零落落地","en":"You can use in ones and twos to indicate that people do things or something happens gradually and in small groups.","ex":{"en":"They lose interest and start drifting away in ones and twos.","cn":"他们没了兴趣，开始三三两两地走开了。"}},{"pos":"PHRASE 短语","cn":"一个接一个地；接连地；陆续地","en":"You use one after the other or one after another to say that actions or events happen with very little time between them.","ex":{"en":"My three guitars broke one after the other","cn":"我的3把吉他陆续都坏了。"}},{"pos":"PHRASE 短语","cn":"（用于节目中介绍演员、歌手或其他名人）绝无仅有的，独一无二的","en":"The one and only can be used in front of the name of an actor, singer, or other famous person when they are being introduced on a show.","ex":{"en":"...one of the greatest ever rock performers, the one and only Tina Turner.","cn":"史上最伟大的摇滚乐手之一，举世无双的蒂娜·特纳"}},{"pos":"PHRASE 短语","cn":"逐个地；依次地","en":"You can use one by one to indicate that people do things or that things happen in sequence, not all at the same time.","ex":{"en":"We went into the room one by one","cn":"我们挨个儿走进房间。"}},{"pos":"PHRASE 短语","cn":"（一组事物或人之中的）或者这个或者那个，有一个","en":"You use one or other to refer to one or more things or people in a group, when it does not matter which particular one or ones are thought of or chosen.","ex":{"en":"One or other of the two women was wrong.","cn":"这两个女人当中有一个人错了。"}},{"pos":"PHRASE 短语","cn":"一两个；几个","en":"One or two means a few.","ex":{"en":"We may make one or two changes","cn":"我们可以作一两处改动。"}},{"pos":"PHRASE 短语","cn":"不大可能（做…)的人","en":"If you say that someone is not one to do something, you think that it is very unlikely that they would do it because it is not their normal behaviour.","ex":{"en":"I'm not one to waste time on just anyone.","cn":"我可不是个随便浪费时间在任何人身上的人。"}},{"pos":"PHRASE 短语","cn":"略胜…一筹；占…的上风","en":"If you try to get one up on someone, you try to gain an advantage over them.","ex":{"en":"...the competitive kind who will see this as the opportunity to be one up on you.","cn":"具有竞争意识、将此视作占据上风的契机的那种人"}},{"pos":"","cn":"","en":"one and all→see: ; one another→see: ; one thing after another→see: ; to pull a fast one→see: ; of one mind→see: ; in one piece→see: ; put one over on→see: ;"}]},"examples":[{"en":"The Scottish legal system is not the same as the English system, is better than … as the English one.","cn":"用 The Scottish legal system is not the same as the English system（苏格兰法制与英格兰法制不同）胜于用 ... as the English one。"},{"en":"It's a public relations office, a press office and a private office all in one.","cn":"那儿既是公关办公室，也是新闻办公室，又是私人办公室：三位一体。"}]},"ones":{"oxford":{"phon":"wʌn","pos":"number","senses":[{"en":"the number 1","cn":"一"},{"en":"used in formal language or for emphasis before hundred , thousand , etc., or before a unit of measurement （","cn":"正式用语或表示强调，用在 hundred、thousand 等或度量单位之前）一"}]}},"onslaught":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"攻击；袭击;猛攻","en":"An onslaught on someone or something is a very violent, forceful attack against them.","ex":{"en":"The attackers launched another vicious onslaught on their victim","cn":"袭击者再度凶残地攻击受害人。"}},{"pos":"N-COUNT 可数名词","cn":"（常指难以应付的）大批，大量","en":"If you refer to an onslaught of something, you mean that there is a large amount of it, often so that it is very difficult to deal with.","ex":{"en":"The onslaught of orders should keep aircraft manufacturers busy for some time.","cn":"纷至沓来的订单应该会让飞机制造商忙碌一段时间。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an act of using weapons against an enemy in a war","cn":""},{"en":"an occasion when an army enters a country and tries to take control of it","cn":""},{"en":"a short attack on a place by soldiers or planes, intended to cause damage but not take control","cn":""}]},"vocab":{"pos":"1 n 2 n","senses":[{"en":"Onslaught is a military term that refers to an attack against an enemy. It's safe to say that no one wants to be caught on the receiving end of an onslaught , because there will be lots of danger, destruction and probably death."}]},"collocations":{"phrases":["ADJ. sudden She could not withstand such a sudden onslaught. | first, initial | latest | renewed | verbal","VERB + ONSLAUGHT face to face the verbal onslaught of an angry teenager | resist, survive, withstand | launch, mount","PREP. ~ against/on a renewed onslaught against the proposed bill | ~ from the latest onslaught from the Russian team"]},"media":{"uk":"media/ldoce/hwd/bre/c/onslaught0205.mp3","us":"media/ldoce/hwd/ame/f/onslaught.mp3"},"examples":[{"en":"The town survives the onslaught of tourists every summer.","cn":"每年夏天，这座小城都要熬过一段旅游者蜂拥而至的苦日子。"},{"en":"the enemy onslaught on our military forces","cn":"敌军对我军的进攻"}],"oxford":{"phon":"ˈɒnslɔːt","pos":"noun","senses":[{"en":"a strong or violent attack","cn":"攻击；猛攻","lab":"figurative","ex":{"en":"His approach was met with a vicious onslaught.","cn":"他的方法遭到了严厉的批评。"}}]}},"onion":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"洋葱；洋葱头","en":"An onion is a round vegetable with a brown skin that grows underground. It has many white layers on its inside which have a strong, sharp smell and taste.","ex":{"en":"Will you chop an onion up for me?","cn":"你能帮我把一个洋葱切碎吗？"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a round white vegetable with a brown, red, or white skin and many layers. Onions have a strong taste and smell","cn":"洋葱（头）"}]},"collocations":{"phrases":["ADJ. raw | pickled | spring, red, Spanish","VERB + ONION chop, peel, slice | brown, soften | cook, fry, saute | garnish sth with Garnish with a little chopped spring onion. | grow","ONION + NOUN ring | soup | skin | set | dome","PHRASES cheese and onion cheese and onion flavoured crisps | sage and onion sage and onion stuffing •"]},"media":{"img":["media/ldoce/img/onion.jpg","media/thumb/onion.jpg"],"uk":"media/ldoce/hwd/bre/1/onion0205.mp3","us":"media/ldoce/hwd/ame/d/onion.mp3"},"examples":[{"en":"Chop the onions finely.","cn":"把洋葱切碎。"},{"en":"French onion soup","cn":"法式洋葱汤"}],"oxford":{"phon":"ˈʌnjən","pos":"noun","senses":[{"en":"a round vegetable with many layers inside each other and a brown, red or white skin. Onions have a strong smell and taste.","cn":"洋葱；葱头","ex":{"en":"Chop the onions finely.","cn":"把洋葱切细。"}}]}}});
